          template: "import { Navigate } from \"react-router-dom\";\nimport PagePrivee from \"./pages/PagePrivee\";\n\nfunction RouteProtegee({ connecte }) {\n  // retournez la bonne élément selon connecte\n}\n\nexport default RouteProtegee;",
