          question: "Ajoutez la route 404 : toute adresse inconnue doit afficher `PageIntrouvable`.",
          template: "import { BrowserRouter, Routes, Route } from \"react-router-dom\";\nimport Accueil from \"./pages/Accueil\";\nimport PageIntrouvable from \"./pages/PageIntrouvable\";\n\nfunction App() {\n  return (\n    <BrowserRouter>\n      <Routes>\n        <Route path=\"/\" element={<Accueil />} />\n        {/* ajoutez la route par défaut */}\n      </Routes>\n    </BrowserRouter>\n  );\n}",
          solution: "import { BrowserRouter, Routes, Route } from \"react-router-dom\";\nimport Accueil from \"./pages/Accueil\";\nimport PageIntrouvable from \"./pages/PageIntrouvable\";\n\nfunction App() {\n  return (\n    <BrowserRouter>\n      <Routes>\n        <Route path=\"/\" element={<Accueil />} />\n        <Route path=\"*\" element={<PageIntrouvable />} />\n      </Routes>\n    </BrowserRouter>\n  );\n}",
